solutionCode:
pub fn empilha(mut pilha: String, letra: &str) -> usize {
    fn empurra(texto: &mut String, pedaco: &str) {
        texto.push_str(pedaco);
    }
    empurra(&mut pilha, letra);
    pilha.len()
}

testsCode:
use desafio::empilha;

#[test]
fn testa_a_pilha_do_placar() {
    assert_eq!(empilha(String::from("Placar"), " 10"), 9);
}

#[test]
fn testa_a_pilha_do_texto_vazio() {
    assert_eq!(empilha(String::from(""), "x"), 1);
}
